{"content": "# -*- coding: utf-8 -*-
"""Validate the extraction and copy it to the output path."""
import json, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from base import PAPER
from build import doc  # noqa: F401  (build.py writes extraction.json on import)

SCHEMA = "/home/user/gp-rarelink/pipeline/extract/claude_code/schema_ha20_v5.json"
OUT = "/home/user/gp-rarelink/data/extracted/ha20/ow-ha20/per_paper/39125844.json"

schema = json.load(open(SCHEMA, encoding="utf-8"))
fields = {t["name"]: [f["name"] for f in t["fields"]] for t in schema["tables"]}

problems = []
for tname, rows in doc["tables"].items():
    want = fields[tname]
    for i, r in enumerate(rows):
        if set(r) != set(want):
            problems.append((tname, i, "field mismatch", sorted(set(want) ^ set(r))))
        for fname, cellv in r.items():
            if not (isinstance(cellv, dict) and set(cellv) == {"value", "span"}):
                problems.append((tname, i, fname, "not a cell", cellv))
                continue
            sp = cellv["span"]
            spans = sp if isinstance(sp, list) else ([sp] if sp else [])
            for s in spans:
                if s is not None and s not in PAPER:
                    problems.append((tname, i, fname, "span not verbatim", s))
            if cellv["value"] not in (None, "not reported") and not spans:
                problems.append((tname, i, fname, "missing span", cellv["value"]))

# enum checks
ENUM = {}
for t in schema["tables"]:
    for f in t["fields"]:
        if f["enum_values"]:
            ENUM[(t["name"], f["name"])] = f["enum_values"]
for tname, rows in doc["tables"].items():
    for i, r in enumerate(rows):
        for fname, cellv in r.items():
            key = (tname, fname)
            if key in ENUM and cellv["value"] is not None and cellv["value"] not in ENUM[key]:
                problems.append((tname, i, fname, "bad enum", cellv["value"]))

print("problems:", len(problems))
for p in problems[:30]:
    print(p)

labels = {r["individual_label_in_paper"]["value"] for r in doc["tables"]["individuals"]}
for tname in ("variants", "phenotypic_features", "phenotype_checklist"):
    for r in doc["tables"][tname]:
        if r["individual_label_in_paper"] != r["individual_label_in_paper"]:
            problems.append("label")
        lb = r["individual_label_in_paper"]
        if not isinstance(lb, dict):
            lb = lb
        val = lb["value"] if isinstance(lb, dict) else lb
        if val not in labels:
            problems.append((tname, "unknown label", val))
print("unknown-label problems:", len([p for p in problems if p and "unknown label" in str(p)]))

# every individual has 20 checklist rows
from collections import Counter
cnt = Counter(r["individual_label_in_paper"] for r in doc["tables"]["phenotype_checklist"])
print("checklist counts ok:", set(cnt.values()), len(cnt), len(labels))

json.dump(doc, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print("written", OUT)
print({k: len(v) for k, v in doc["tables"].items()})
